internal object Util {
    val NAME_RE = Regex("^[A-Za-z][A-Za-z0-9_]{0,63}$")
    val ID_RE = Regex("^[A-Za-z0-9_.:-]{1,64}$")
    val KEY_RE = Regex("^[a-z0-9]{8,16}$")
    private val WRAPPER_RE = Regex("^[a-z][a-z0-9-]{0,31}$")

