        var digits = 0
        var innerUpper = false
        var allUpper = length > 0
        for (i in from until to) {
            val c = s[i]
            if (isDigit(c)) digits++
            if (isUpper(c)) {
                if (i > from) innerUpper = true
            } else {
                allUpper = false
            }
        }
        if (digits == 0) {
            if (hint == 3 || !innerUpper || allUpper) return false
            return !camelWord(s, from, to)
